code.cpp:
class Solution {
public:
    int longestCycle(vector<int>& edges) {
        int n = edges.size();
        vector<int> visited(n, -1);
        int ans = -1;
        int step = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] != -1) continue;
            int curr = i;
            int startStep = step;
            while (curr != -1 && visited[curr] == -1) {
                visited[curr] = step;
                step++;
                curr = edges[curr];
            }
            if (curr != -1 && visited[curr] >= startStep) {
                ans = max(ans, step - visited[curr]);
            }
        }
        return ans;
    }
};
